#include "ReservationList.h"
#include <iostream>
ReservationList::ReservationList():head(nullptr){} ReservationList::~ReservationList(){while(head){Node*n=head->next;delete head;head=n;}} bool ReservationList::contains(int id)const{for(Node*p=head;p;p=p->next)if(p->data.getId()==id)return true;return false;} bool ReservationList::insert(const Reservation&r){if(contains(r.getId()))return false;Node*n=new Node(r);n->next=head;head=n;return true;} bool ReservationList::remove(int id,Reservation&out){Node*p=head,*prev=nullptr;while(p){if(p->data.getId()==id){out=p->data;if(prev)prev->next=p->next;else head=p->next;delete p;return true;}prev=p;p=p->next;}return false;} void ReservationList::display()const{if(!head){std::cout<<"No active reservations.\n";return;}for(Node*p=head;p;p=p->next)p->data.display();}
